package com.crm.fees.service;
import com.crm.fees.repository.FeeReportRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.PageRequest;import java.time.LocalDate;import java.math.BigDecimal;import java.util.*;
@Service @Transactional(readOnly=true) public class FeeReportService {
 public record Line(String kind,String offeringId,String title,String customerId,String currency,long count,String hours,String amount){}
 public record Total(String kind,String currency,long count,String hours,String amount){}
 public record CustomerTotal(String kind,String customerId,String currency,long count,String hours,String amount){}
 public record Report(LocalDate from,LocalDate to,String policy,List<Line> lines,List<Total> totals,List<CustomerTotal> customerTotals){}
 private final FeeReportRepository repository;public FeeReportService(FeeReportRepository r){repository=r;}
 public Report read(LocalDate from,LocalDate to){return read(from,to,null,null);}
 public Report read(LocalDate from,LocalDate to,Long offering,String customer){FeeAuthorization.admin();FeeCycleService.period(from,to);if(offering!=null&&offering<=0||customer!=null&&(customer.isBlank()||customer.length()>50))throw new IllegalArgumentException("Invalid report filter");var page=PageRequest.of(0,1001);var recorded=repository.recorded(from,to,offering,customer,page);var pending=repository.unrecorded(from,to,offering,customer,page);if(recorded.size()+pending.size()>1000)throw new IllegalArgumentException("Report exceeds 1000 groups; choose a shorter period");List<Line> lines=new ArrayList<>();add(lines,recorded,"RECORDED_FEE");add(lines,pending,"UNRECORDED_TIME");Map<String,List<Line>> groups=new TreeMap<>();for(var line:lines)groups.computeIfAbsent(line.kind()+"|"+line.currency(),k->new ArrayList<>()).add(line);List<Total> totals=new ArrayList<>();for(var rows:groups.values()){var first=rows.getFirst();boolean known=first.currency()!=null;String hours=rows.stream().anyMatch(l->l.hours()==null)?null:rows.stream().map(l->new BigDecimal(l.hours())).reduce(BigDecimal.ZERO,BigDecimal::add).toPlainString();String amount=known?rows.stream().map(l->new BigDecimal(l.amount())).reduce(BigDecimal.ZERO,BigDecimal::add).toPlainString():null;totals.add(new Total(first.kind(),first.currency(),rows.stream().mapToLong(Line::count).sum(),hours,amount));}Map<String,List<Line>> customers=new TreeMap<>();for(var line:lines)customers.computeIfAbsent(line.kind()+"|"+line.currency()+"|"+line.customerId(),k->new ArrayList<>()).add(line);List<CustomerTotal> customerTotals=new ArrayList<>();for(var rows:customers.values()){var first=rows.getFirst();String hours=rows.stream().anyMatch(l->l.hours()==null)?null:rows.stream().map(l->new BigDecimal(l.hours())).reduce(BigDecimal.ZERO,BigDecimal::add).toPlainString();String amount=first.currency()==null?null:rows.stream().map(l->new BigDecimal(l.amount())).reduce(BigDecimal.ZERO,BigDecimal::add).toPlainString();customerTotals.add(new CustomerTotal(first.kind(),first.customerId(),first.currency(),rows.stream().mapToLong(Line::count).sum(),hours,amount));}return new Report(from,to,"TECHNICAL_NON_REGULATORY;RECORDED_IS_NOT_INVOICED",List.copyOf(lines),List.copyOf(totals),List.copyOf(customerTotals));}
 private void add(List<Line> lines,List<FeeReportRepository.Row> source,String kind){for(var r:source){if(r.getCount()<0||r.getCurrency()!=null&&(r.getAmount()==null||r.getAmount().signum()<0))throw new IllegalStateException("Invalid fee aggregate");lines.add(new Line(kind,r.getOfferingId()==null?null:r.getOfferingId().toString(),r.getTitle(),r.getCustomerId(),r.getCurrency(),r.getCount(),r.getHours()==null?null:r.getHours().toPlainString(),r.getCurrency()==null?null:r.getAmount().toPlainString()));}}
 public byte[] csv(LocalDate from,LocalDate to){return csv(from,to,null,null);}
 public byte[] csv(LocalDate from,LocalDate to,Long offering,String customer){var report=read(from,to,offering,customer);StringBuilder out=new StringBuilder("\uFEFFclassification,from,to,kind,offering,service,customer,currency,count,hours,amount\r\n");for(var row:report.lines()){Object[] values={"TECHNICAL_NON_REGULATORY",from,to,row.kind(),row.offeringId(),row.title(),row.customerId(),row.currency(),row.count(),row.hours(),row.amount()};for(int i=0;i<values.length;i++){if(i>0)out.append(',');out.append(cell(values[i]));}out.append("\r\n");}return out.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 public static String cell(Object value){String s=value==null?"":value.toString();if(!s.isEmpty()&&(Character.isWhitespace(s.charAt(0))||"=+-@".indexOf(s.charAt(0))>=0))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
}